(function () {
    'use strict';

    var DATA = null;
    var state = { dest: 'all', type: 'all', search: '', favorites: loadFavorites() };
    var cardObserver = null;
    var filtersReady = false;
    var swapTimer = null;

    function loadFavorites() {
      try { return JSON.parse(localStorage.getItem('mtTopAttractions') || '[]'); }
      catch (e) { return []; }
    }
    function saveFavorites() {
      try { localStorage.setItem('mtTopAttractions', JSON.stringify(state.favorites)); }
      catch (e) {}
      updateFavUI();
    }
    function favKey(destId, rank) { return destId + ':' + rank; }
    function isFav(destId, rank) { return state.favorites.indexOf(favKey(destId, rank)) !== -1; }
    function toggleFav(destId, rank, btn) {
      var k = favKey(destId, rank);
      var i = state.favorites.indexOf(k);
      if (i === -1) state.favorites.push(k);
      else state.favorites.splice(i, 1);
      if (btn) btn.classList.toggle('on', i === -1);
      saveFavorites();
    }

    function updateFavUI() {
      document.getElementById('favCount').textContent = String(state.favorites.length);
      renderFavPanel();
    }

    function flagHtml(code, sizeClass) {
      if (!code) return '';
      return '<span class="flag-icon ' + (sizeClass || 'flag-chip') + ' flag-' + code + '" role="img" aria-hidden="true"></span>';
    }

    function imageUrl(item) {
      if (item.image) return item.image;
      if (item.imageFile) {
        return 'https://commons.wikimedia.org/wiki/Special:FilePath/' + encodeURIComponent(item.imageFile) + '?width=800';
      }
      return '';
    }

    function bindImage(img, item) {
      if (!img) return;
      var url = imageUrl(item);
      var fallback = item.imageFile
        ? 'https://commons.wikimedia.org/wiki/Special:FilePath/' + encodeURIComponent(item.imageFile) + '?width=800'
        : '';
      img.src = url;
      img.alt = item.nameHe;
      img.onerror = function () {
        if (fallback && img.src !== fallback) { img.src = fallback; return; }
        img.remove();
      };
    }

    function flatAttractions() {
      var list = [];
      (DATA.destinations || []).forEach(function (d) {
        (d.attractions || []).forEach(function (a) {
          list.push({
            destId: d.id,
            destName: d.nameHe,
            destFlag: d.flag,
            countryCode: d.countryCode,
            guideUrl: d.guideUrl,
            rank: a.rank,
            nameHe: a.nameHe,
            nameEn: a.nameEn,
            type: a.type,
            typeKey: a.typeKey,
            ages: a.ages,
            duration: a.duration,
            why: a.why,
            location: a.location,
            hours: a.hours,
            price: a.price,
            tip: a.tip,
            website: a.website,
            highlights: a.highlights || [],
            image: a.image,
            imageFile: a.imageFile,
            imageCredit: a.imageCredit || 'Wikimedia Commons'
          });
        });
      });
      return list;
    }

    function matchesFilters(item) {
      if (state.dest !== 'all' && item.destId !== state.dest) return false;
      if (state.type !== 'all' && item.typeKey !== state.type) return false;
      if (state.search) {
        var q = state.search.toLowerCase();
        var hay = (item.nameHe + ' ' + item.nameEn + ' ' + item.destName).toLowerCase();
        if (hay.indexOf(q) === -1) return false;
      }
      return true;
    }

    function positionThumb(btn, thumb, scrollEl) {
      if (!btn || !thumb || !scrollEl) return;
      var base = scrollEl.getBoundingClientRect();
      var rect = btn.getBoundingClientRect();
      var x = rect.left - base.left + scrollEl.scrollLeft;
      thumb.style.width = rect.width + 'px';
      thumb.style.transform = 'translate3d(' + x + 'px, 0, 0)';
    }

    function scrollChipIntoView(btn, scrollEl) {
      if (!btn || !scrollEl) return;
      var left = btn.offsetLeft - scrollEl.clientWidth / 2 + btn.offsetWidth / 2;
      scrollEl.scrollTo({ left: Math.max(0, left), behavior: 'smooth' });
    }

    function updateTypeUI(activeBtn) {
      document.querySelectorAll('.type-tab').forEach(function (b) {
        var on = b.dataset.type === state.type;
        b.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      var thumb = document.getElementById('typeThumb');
      var list = document.getElementById('typeList');
      var btn = activeBtn || list.querySelector('[data-type="' + state.type + '"]');
      positionThumb(btn, thumb, list);
    }

    function updateDestUI(activeBtn) {
      document.querySelectorAll('.dest-btn').forEach(function (b) {
        var on = b.dataset.dest === state.dest;
        b.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      document.querySelectorAll('.dest-tile').forEach(function (b) {
        var on = b.dataset.dest === state.dest;
        b.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      updateDestPickerLabel();
      var thumb = document.getElementById('destThumb');
      var viewport = document.getElementById('destViewport');
      var btn = activeBtn || document.querySelector('.dest-btn[data-dest="' + state.dest + '"]');
      if (thumb && viewport && btn) {
        positionThumb(btn, thumb, viewport);
        scrollChipIntoView(btn, viewport);
      }
    }

    function destDisplayFor(id) {
      if (id === 'all') {
        return { name: 'כל היעדים', flag: '🌍', pickerHtml: '🌍 כל היעדים' };
      }
      var d = (DATA.destinations || []).find(function (x) { return x.id === id; });
      if (!d) return { name: id, flag: '', pickerHtml: id };
      return {
        name: d.nameHe,
        flag: flagHtml(d.countryCode, 'flag-chip'),
        pickerHtml: flagHtml(d.countryCode, 'flag-chip') + ' ' + d.nameHe
      };
    }

    function updateDestPickerLabel() {
      var el = document.getElementById('destPickerValue');
      if (!el || !DATA) return;
      var info = destDisplayFor(state.dest);
      el.innerHTML = info.pickerHtml;
    }

    function openDestSheet() {
      var sheet = document.getElementById('destSheet');
      var trigger = document.getElementById('destPickerTrigger');
      if (!sheet) return;
      sheet.classList.add('open');
      sheet.setAttribute('aria-hidden', 'false');
      if (trigger) trigger.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
    }

    function closeDestSheet() {
      var sheet = document.getElementById('destSheet');
      var trigger = document.getElementById('destPickerTrigger');
      if (!sheet) return;
      sheet.classList.remove('open');
      sheet.setAttribute('aria-hidden', 'true');
      if (trigger) trigger.setAttribute('aria-expanded', 'false');
      if (!document.body.classList.contains('modal-open')) {
        document.body.style.overflow = '';
      }
    }

    function setType(typeId, btn) {
      if (state.type === typeId) return;
      state.type = typeId;
      updateTypeUI(btn);
      animateRender();
    }

    function setDest(destId, btn) {
      if (state.dest === destId) return;
      state.dest = destId;
      updateDestUI(btn);
      try {
        if (destId === 'all') {
          if (location.hash) history.replaceState(null, '', location.pathname + location.search);
        } else {
          history.replaceState(null, '', '#dest-' + destId);
        }
      } catch (e) {}
      animateRender();
    }

    function destIdFromHash() {
      var h = (location.hash || '').replace(/^#/, '');
      return h.indexOf('dest-') === 0 ? h.slice(5) : '';
    }

    function isValidDestId(id) {
      return !!(id && DATA && (DATA.destinations || []).some(function (d) { return d.id === id; }));
    }

    function scrollToDestSection(id) {
      requestAnimationFrame(function () {
        requestAnimationFrame(function () {
          var el = document.getElementById('dest-' + id);
          if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
      });
    }

    function applyHashDest() {
      var id = destIdFromHash();
      if (!isValidDestId(id)) return;
      if (state.dest !== id) {
        state.dest = id;
        updateDestUI();
        renderAppContent();
      }
      scrollToDestSection(id);
    }

    function animateRender() {
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        renderAppContent();
        return;
      }
      var app = document.getElementById('app');
      clearTimeout(swapTimer);
      app.classList.remove('is-entering');
      app.classList.add('is-leaving');
      swapTimer = setTimeout(function () {
        renderAppContent();
        app.classList.remove('is-leaving');
        app.classList.add('is-entering');
        swapTimer = setTimeout(function () {
          app.classList.remove('is-entering');
        }, 420);
      }, 220);
    }

    function buildFilters() {
      if (filtersReady) return;
      filtersReady = true;

      var typeList = document.getElementById('typeList');
      (DATA.typeFilters || []).forEach(function (f) {
        var b = document.createElement('button');
        b.type = 'button';
        b.className = 'type-tab';
        b.dataset.type = f.id;
        b.setAttribute('role', 'tab');
        b.textContent = f.icon + ' ' + f.label;
        b.setAttribute('aria-selected', state.type === f.id ? 'true' : 'false');
        b.addEventListener('click', function () { setType(f.id, b); });
        typeList.appendChild(b);
      });

      var destButtons = document.getElementById('destButtons');
      function addDestBtn(id, labelHtml) {
        var b = document.createElement('button');
        b.type = 'button';
        b.className = 'dest-btn';
        b.dataset.dest = id;
        b.setAttribute('role', 'tab');
        b.innerHTML = labelHtml;
        b.setAttribute('aria-selected', state.dest === id ? 'true' : 'false');
        b.addEventListener('click', function () { setDest(id, b); });
        destButtons.appendChild(b);
        return b;
      }

      addDestBtn('all', '<span class="dest-btn__icon">🌍</span><span>כל היעדים</span>');
      (DATA.destinations || []).forEach(function (d) {
        addDestBtn(d.id, flagHtml(d.countryCode, 'flag-chip') + '<span>' + d.nameHe + '</span>');
      });

      var sheetGrid = document.getElementById('destSheetGrid');
      function addDestTile(id, name, flagHtmlInner, extraClass) {
        var t = document.createElement('button');
        t.type = 'button';
        t.className = 'dest-tile' + (extraClass ? ' ' + extraClass : '');
        t.dataset.dest = id;
        t.setAttribute('role', 'tab');
        t.setAttribute('aria-selected', state.dest === id ? 'true' : 'false');
        t.innerHTML =
          '<span class="dest-tile__flag">' + flagHtmlInner + '</span>' +
          '<span class="dest-tile__name">' + name + '</span>' +
          '<span class="dest-tile__badge">Top 5</span>';
        t.addEventListener('click', function () {
          var barBtn = document.querySelector('.dest-btn[data-dest="' + id + '"]');
          setDest(id, barBtn);
          closeDestSheet();
        });
        sheetGrid.appendChild(t);
      }

      addDestTile('all', 'כל היעדים', '🌍', 'dest-tile--all');
      (DATA.destinations || []).forEach(function (d) {
        addDestTile(d.id, d.nameHe, flagHtml(d.countryCode, 'flag-chip'), '');
      });

      var destPickerTrigger = document.getElementById('destPickerTrigger');
      var destSheetClose = document.getElementById('destSheetClose');
      var destSheetBackdrop = document.getElementById('destSheetBackdrop');
      if (destPickerTrigger) destPickerTrigger.addEventListener('click', openDestSheet);
      if (destSheetClose) destSheetClose.addEventListener('click', closeDestSheet);
      if (destSheetBackdrop) destSheetBackdrop.addEventListener('click', closeDestSheet);

      requestAnimationFrame(function () {
        updateTypeUI();
        updateDestUI();
      });

      window.addEventListener('resize', function () {
        updateTypeUI();
        updateDestUI();
      });
    }

    function renderFilters() {
      buildFilters();
      updateTypeUI();
      updateDestUI();
    }

    function createCard(item, delay) {
      var card = document.createElement('article');
      card.className = 'card';
      card.dataset.dest = item.destId;
      card.dataset.type = item.typeKey;
      card.style.transitionDelay = (delay * 0.06) + 's';

      var favBtn = document.createElement('button');
      favBtn.type = 'button';
      favBtn.className = 'card__fav' + (isFav(item.destId, item.rank) ? ' on' : '');
      favBtn.innerHTML = isFav(item.destId, item.rank) ? '❤️' : '🤍';
      favBtn.setAttribute('aria-label', 'הוסף לרשימה');
      favBtn.addEventListener('click', function (e) {
        e.stopPropagation();
        toggleFav(item.destId, item.rank, favBtn);
        favBtn.innerHTML = isFav(item.destId, item.rank) ? '❤️' : '🤍';
      });

      card.innerHTML =
        '<div class="card__media" data-fallback="' + (item.countryCode || '') + '">' +
          '<img alt="" loading="lazy" decoding="async">' +
          '<span class="card__rank">' + item.rank + '</span>' +
        '</div>' +
        '<div class="card__body">' +
          '<div class="card__meta">' +
            '<span class="pill pill--dest">' + flagHtml(item.countryCode, 'flag-pill') + ' ' + item.destName + '</span>' +
            '<span class="pill pill--muted">' + item.type + '</span>' +
          '</div>' +
          '<div class="card__title">' + item.nameHe + '</div>' +
          '<div class="card__en">' + item.nameEn + '</div>' +
          '<p class="card__why">' + item.why + '</p>' +
        '</div>';
      bindImage(card.querySelector('.card__media img'), item);
      card.querySelector('.card__media').appendChild(favBtn);

      card.addEventListener('click', function () { openDrawer(item); });
      return card;
    }

    function renderAppContent() {
      var app = document.getElementById('app');
      app.innerHTML = '';
      var items = flatAttractions().filter(matchesFilters);
      document.getElementById('statVisible').textContent = String(items.length);

      if (state.dest === 'all') {
        var byDest = {};
        items.forEach(function (it) {
          if (!byDest[it.destId]) byDest[it.destId] = { meta: it, items: [] };
          byDest[it.destId].items.push(it);
        });
        var destIds = Object.keys(byDest);
        if (!destIds.length) {
          app.innerHTML = '<p class="empty">לא נמצאו אטרקציות - נסו סינון אחר 🔍</p>';
          return;
        }
        destIds.forEach(function (id) {
          var group = byDest[id];
          var dest = DATA.destinations.find(function (d) { return d.id === id; });
          var head = document.createElement('div');
          head.className = 'section-head';
          head.id = 'dest-' + id;
          head.innerHTML = '<h2>' + flagHtml(dest ? dest.countryCode : '', 'flag-chip') + ' ' + (dest ? dest.nameHe : id) + '</h2>' +
            '<a href="' + (dest ? dest.guideUrl : '#') + '">למדריך המלא</a>';
          app.appendChild(head);
          var grid = document.createElement('div');
          grid.className = 'grid';
          group.items.sort(function (a, b) { return a.rank - b.rank; });
          group.items.forEach(function (it, i) { grid.appendChild(createCard(it, i)); });
          app.appendChild(grid);
          requestAnimationFrame(function () { head.classList.add('visible'); });
        });
      } else {
        var dest = DATA.destinations.find(function (d) { return d.id === state.dest; });
        if (dest) {
          var head = document.createElement('div');
          head.className = 'section-head visible';
          head.id = 'dest-' + state.dest;
          head.innerHTML = '<h2>' + flagHtml(dest.countryCode, 'flag-chip') + ' ' + dest.nameHe + '</h2><a href="' + dest.guideUrl + '">למדריך המלא</a>';
          app.appendChild(head);
        }
        var grid = document.createElement('div');
        grid.className = 'grid';
        if (!items.length) {
          grid.innerHTML = '<p class="empty">לא נמצאו אטרקציות - נסו סינון אחר 🔍</p>';
        } else {
          items.sort(function (a, b) { return a.rank - b.rank; });
          items.forEach(function (it, i) { grid.appendChild(createCard(it, i)); });
        }
        app.appendChild(grid);
      }

      observeCards();
    }

    function renderApp() {
      renderAppContent();
    }

    function observeCards() {
      if (cardObserver) cardObserver.disconnect();
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        document.querySelectorAll('.card').forEach(function (c) { c.classList.add('visible'); });
        return;
      }
      cardObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (e) {
          if (e.isIntersecting) {
            e.target.classList.add('visible');
            cardObserver.unobserve(e.target);
          }
        });
      }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
      document.querySelectorAll('.card:not(.visible)').forEach(function (c) { cardObserver.observe(c); });
    }

    function openDrawer(item) {
      closeDestSheet();
      var hero = document.getElementById('drawerHero');
      hero.className = 'drawer__hero is-loading';
      hero.innerHTML = '<img alt=""><span class="drawer__rank">#' + item.rank + '</span>';
      bindImage(hero.querySelector('img'), item);
      hero.querySelector('img').addEventListener('load', function () { hero.classList.remove('is-loading'); });
      hero.querySelector('img').addEventListener('error', function () { hero.classList.remove('is-loading'); });

      document.getElementById('drawerTitle').textContent = item.nameHe;
      document.getElementById('drawerEn').textContent = item.nameEn;

      var facts = [
        { label: 'יעד', val: flagHtml(item.countryCode, 'flag-drawer') + ' ' + item.destName },
        { label: 'סוג', val: item.type },
        { label: 'גילאים', val: item.ages },
        { label: 'זמן מומלץ', val: item.duration }
      ];
      if (item.location) facts.push({ label: 'מיקום', val: item.location, wide: true });
      if (item.hours) facts.push({ label: 'שעות', val: item.hours, wide: true });
      if (item.price) facts.push({ label: 'מחיר משוער', val: item.price, wide: true });

      document.getElementById('drawerFacts').innerHTML = facts.map(function (f) {
        return '<div class="fact' + (f.wide ? ' fact--wide' : '') + '"><div class="fact__label">' + f.label + '</div><div class="fact__val">' + f.val + '</div></div>';
      }).join('');

      var hl = document.getElementById('drawerHighlights');
      if (item.highlights && item.highlights.length) {
        hl.hidden = false;
        hl.innerHTML = '<h4>למה לילדים?</h4><ul>' + item.highlights.map(function (h) { return '<li>' + h + '</li>'; }).join('') + '</ul>';
      } else { hl.hidden = true; hl.innerHTML = ''; }

      document.getElementById('drawerWhy').textContent = item.why;

      var tipEl = document.getElementById('drawerTip');
      if (item.tip) {
        tipEl.hidden = false;
        tipEl.innerHTML = '<strong>💡 טיפ מהמדריך שלנו</strong> ' + item.tip;
      } else { tipEl.hidden = true; tipEl.innerHTML = ''; }

      var credit = 'תמונה: ' + item.imageCredit + ' (שימוש חופשי)';
      if (item.website) credit += ' · <a href="' + item.website + '" target="_blank" rel="noopener">אתר רשמי ↗</a>';
      document.getElementById('drawerCredit').innerHTML = credit;

      var on = isFav(item.destId, item.rank);
      var actions = '<button type="button" class="btn btn--primary" id="drawerFavBtn">' + (on ? '❤️ ברשימה שלי' : '🤍 שמור לרשימה') + '</button>';
      if (item.website) {
        actions += '<a class="btn btn--ghost" href="' + item.website + '" target="_blank" rel="noopener" style="text-align:center;justify-content:center">אתר האטרקציה ↗</a>';
      }
      actions += '<a class="btn btn--ghost" href="' + item.guideUrl + '" style="text-align:center;justify-content:center">למדריך ' + item.destName + ' ←</a>';
      actions += '<button type="button" class="btn btn--ghost" id="drawerBackBtn" style="text-align:center;justify-content:center">חזרה לרשימה</button>';
      document.getElementById('drawerActions').innerHTML = actions;
      document.getElementById('drawerBackBtn').addEventListener('click', closeDrawer);
      document.getElementById('drawerFavBtn').addEventListener('click', function () {
        toggleFav(item.destId, item.rank);
        var nowOn = isFav(item.destId, item.rank);
        this.textContent = nowOn ? '❤️ ברשימה שלי' : '🤍 שמור לרשימה';
        document.querySelectorAll('.card__fav').forEach(function (b) {
          var card = b.closest('.card');
          if (!card) return;
        });
        renderAppContent();
      });
      document.getElementById('drawerOverlay').classList.add('open');
      document.getElementById('drawer').classList.add('open');
      document.body.classList.add('modal-open');
      document.body.style.overflow = 'hidden';
    }

    function closeDrawer() {
      document.getElementById('drawerOverlay').classList.remove('open');
      document.getElementById('drawer').classList.remove('open');
      document.body.classList.remove('modal-open');
      document.body.style.overflow = '';
    }

    function renderFavPanel() {
      var list = document.getElementById('favList');
      if (!state.favorites.length) {
        list.innerHTML = '<p style="color:#64748b;text-align:center;padding:24px">עדיין אין מועדפים - לחצו 🤍 על כרטיס</p>';
        return;
      }
      list.innerHTML = '';
      state.favorites.forEach(function (k) {
        var parts = k.split(':');
        var destId = parts[0];
        var rank = parseInt(parts[1], 10);
        var item = flatAttractions().find(function (a) { return a.destId === destId && a.rank === rank; });
        if (!item) return;
        var row = document.createElement('div');
        row.className = 'fav-item';
        row.innerHTML =
          '<img alt="">' +
          '<div class="fav-item__text"><div class="fav-item__name">' + item.nameHe + '</div><div class="fav-item__dest">' + flagHtml(item.countryCode, 'flag-pill') + ' ' + item.destName + ' · #' + item.rank + '</div></div>';
        bindImage(row.querySelector('img'), item);
        row.style.cursor = 'pointer';
        row.addEventListener('click', function () {
          document.getElementById('favPanel').classList.remove('open');
          openDrawer(item);
        });
        list.appendChild(row);
      });
    }

    document.getElementById('drawerClose').addEventListener('click', closeDrawer);
    document.getElementById('drawerOverlay').addEventListener('click', closeDrawer);
    document.addEventListener('keydown', function (e) {
      if (e.key !== 'Escape') return;
      var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
      var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
      if (mobileMenu && mobileMenu.classList.contains('open')) {
        mobileMenu.classList.remove('open');
        if (hamburger) {
          hamburger.setAttribute('aria-expanded', 'false');
          hamburger.setAttribute('aria-label', 'פתח תפריט');
        }
        if (!document.body.classList.contains('modal-open')) document.body.style.overflow = '';
        return;
      }
      var emailOverlay = (document.getElementById("__legacy_emailPopupOverlay") || document.createElement("div"));
      if (emailOverlay && emailOverlay.classList.contains('open')) {
        if (typeof window.closeEmailPopup === 'function') window.closeEmailPopup();
        return;
      }
      var destSheet = document.getElementById('destSheet');
      if (destSheet && destSheet.classList.contains('open')) {
        closeDestSheet();
        return;
      }
      closeDrawer();
      document.getElementById('favPanel').classList.remove('open');
    });

    document.getElementById('btnFavorites').addEventListener('click', function () {
      document.getElementById('favPanel').classList.toggle('open');
      renderFavPanel();
    });
    document.getElementById('favPanelClose').addEventListener('click', function () {
      document.getElementById('favPanel').classList.remove('open');
    });

    var searchTimer;
    document.getElementById('searchInput').addEventListener('input', function () {
      clearTimeout(searchTimer);
      var val = this.value;
      searchTimer = setTimeout(function () {
        state.search = val.trim();
        animateRender();
      }, 200);
    });

    function loadAttractionsData() {
      if (window.__FAMILY_TOP_ATTRACTIONS__) {
        return Promise.resolve(window.__FAMILY_TOP_ATTRACTIONS__);
      }
      return fetch('data/family-top-attractions.json', { cache: 'no-cache' })
        .then(function (r) {
          if (!r.ok) throw new Error('data fetch failed');
          return r.json();
        });
    }

    function bootAttractions(data) {
      DATA = data;
      var hashId = destIdFromHash();
      if (isValidDestId(hashId)) state.dest = hashId;
      document.getElementById('statDest').textContent = String((data.destinations || []).length);
      renderFilters();
      renderAppContent();
      updateFavUI();
      if (hashId) scrollToDestSection(hashId);
    }

    loadAttractionsData()
      .then(bootAttractions)
      .catch(function () {
        document.getElementById('app').innerHTML = '<p class="empty">שגיאה בטעינת הנתונים - רעננו את הדף או נסו שוב מאוחר יותר</p>';
      });

    window.addEventListener('hashchange', applyHashDest);

    /* Site nav */
    var nav = document.getElementById('nav');
    if (nav) {
      window.addEventListener('scroll', function () {
        nav.classList.toggle('scrolled', window.scrollY > 10);
      }, { passive: true });
    }

    var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
    var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
    if (hamburger && mobileMenu) {
      hamburger.addEventListener('click', function (e) {
        e.stopPropagation();
        var drawer = document.getElementById('drawer');
        if (drawer && drawer.classList.contains('open')) closeDrawer();
        var favPanel = document.getElementById('favPanel');
        if (favPanel) favPanel.classList.remove('open');
        var isOpen = mobileMenu.classList.toggle('open');
        hamburger.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        hamburger.setAttribute('aria-label', isOpen ? 'סגור תפריט' : 'פתח תפריט');
        if (!document.body.classList.contains('modal-open')) {
          document.body.style.overflow = isOpen ? 'hidden' : '';
        }
      });
      mobileMenu.querySelectorAll('a').forEach(function (link) {
        link.addEventListener('click', function () {
          mobileMenu.classList.remove('open');
          hamburger.setAttribute('aria-expanded', 'false');
          hamburger.setAttribute('aria-label', 'פתח תפריט');
          var href = link.getAttribute('href') || '';
          if (href === 'tips.html#newsletter' || href === '#newsletter') return;
          if (!document.body.classList.contains('modal-open')) {
            document.body.style.overflow = '';
          }
        });
      });
    }
  })();

(function() {
  try {
    var _sub = new URLSearchParams(window.location.search).get('subscribed');
    if (_sub === '1') localStorage.setItem('mtEmailSubmitted', '1');
  } catch (e) {}

  var overlay = (document.getElementById("__legacy_emailPopupOverlay") || document.createElement("div"));
  var closeBtn = (document.getElementById("__legacy_emailPopupClose") || document.createElement("button"));
  var form = (document.getElementById("__legacy_emailPopupForm") || document.createElement("form"));
  if (!overlay) return;

  var openedAt = 0;
  var plausiblePage = 'family-top-attractions';

  function openPopup(fromNav) {
    if (overlay.classList.contains('open')) {
      if (!fromNav) return;
      openedAt = Date.now();
      if (window.plausible) plausible('Newsletter-Open-Nav', { props: { page: plausiblePage } });
      return;
    }
    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
    openedAt = Date.now();
    if (fromNav && window.plausible) plausible('Newsletter-Open-Nav', { props: { page: plausiblePage } });
  }

  function closePopup() {
    overlay.classList.remove('open');
    var drawer = document.getElementById('drawer');
    if (!drawer || !drawer.classList.contains('open')) document.body.style.overflow = '';
  }

  document.querySelectorAll('a[href="#newsletter"], a[href="tips.html#newsletter"]').forEach(function(link) {
    link.addEventListener('click', function(e) {
      e.preventDefault();
      var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
      var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
      if (mobileMenu && mobileMenu.classList.contains('open')) {
        mobileMenu.classList.remove('open');
        if (hamburger) {
          hamburger.setAttribute('aria-expanded', 'false');
          hamburger.setAttribute('aria-label', 'פתח תפריט');
        }
      }
      openPopup(true);
    });
  });

  if (closeBtn) closeBtn.addEventListener('click', closePopup);
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay && Date.now() - openedAt > 400) closePopup();
  });

  if (form) {
    form.addEventListener('submit', function() {
      try { localStorage.setItem('mtEmailSubmitted', '1'); } catch (e) {}
    });
  }

  window.openEmailPopup = function() { openPopup(true); };
  window.closeEmailPopup = closePopup;
})();

